               (void *pContext,FLuxTraceInactiveDescriptor_Partial *pDescriptor)

{
  ALuxTraceManager *pTraceManager;
  bool bVar1;
  longlong lVar2;
  FTraceInactiveParam inactiveParam;
  int nSourcePlayerIndex;
  
                    /* Read descriptor +0x00 source player index. */
  nSourcePlayerIndex = pDescriptor->nSourcePlayerIndex;
  lVar2 = GetBattleManagerFromWorldContext();
                    /* Resolve BattleManager +0x390 character array and character +0x458 trace
                       manager. */
  if ((((lVar2 != 0) && (-1 < nSourcePlayerIndex)) && (nSourcePlayerIndex < *(int *)(lVar2 + 0x398))
      ) && (pTraceManager =
                 *(ALuxTraceManager **)
                  (*(longlong *)(*(longlong *)(lVar2 + 0x390) + (longlong)nSourcePlayerIndex * 8) +
                  0x458), pTraceManager != (ALuxTraceManager *)0x0)) {
    inactiveParam.bTracePartsId = 0;
    inactiveParam.field1_0x1 = Immediatery;
                    /* Copy descriptor inactive type only when manager trace assets are configured.
                        */
    bVar1 = BuildLuxTraceInactiveParamIfConfigured(pTraceManager,pDescriptor,&inactiveParam);
    if (bVar1) {
                    /* Perform semantic component deactivation and manager slot/hash mutation. */
      ALuxTraceManager_Inactive_Impl(pTraceManager,&inactiveParam);
    }
  }
  return;
}

