/* Purpose:
   Convert MoveVM opcode 0x03EC raw arguments into the exact 8-byte trace-inactive descriptor and
   synchronously broadcast listener collection 19.
   
   Parameters:
   pDispatcher - listener hub; collection 19 is dispatcher-relative +0x858.
   pdwRawInactiveRequest - source player index followed by authored parts selector.
   
   Algorithm:
   Copy source player, normalize the selector through LuxMove_GetModeIndex_Lookup47_B, and
   broadcast. Authored values 0..46 map to trace-parts IDs 1..47. Missing/unknown values, including
   the MoveVM default -1, map to parts ID 0 (all).
   
   Returns:
   void.
   
   Rollback:
   Opcode 0x03EC is semantic trace deactivation, not a no-op presentation request. Preserve this
   source-time boundary and collection order. */

void DispatchLuxTraceInactiveDescriptorFromMoveEvent
               (FLuxVfxDispatcher_Partial *pDispatcher,uint *pdwRawInactiveRequest)

{
  int nSourcePlayerIndex;
  byte bTracePartsId;
  
                    /* Descriptor +0x00: source player index. */
  nSourcePlayerIndex = *pdwRawInactiveRequest;
  bTracePartsId = 0;
                    /* Descriptor +0x04: normalize authored selector; default -1/missing key becomes
                       inactive type 0 (all). */
  bTracePartsId = LuxMove_GetModeIndex_Lookup47_B(pdwRawInactiveRequest[1]);
                    /* Listener collection 19 begins at dispatcher-relative +0x858. */
                    /* Descriptor +0x04 is normalized trace-parts ID; MoveVM default -1 maps to 0
                       (all). */
                    /* Synchronous collection-19 broadcast into the character trace-manager inactive
                       subscriber. */
  ProcessAndCompactCallbackEntries
            ((FCallbackEntryCollection_Partial *)(pDispatcher + 0x10b),&nSourcePlayerIndex);
                    /* Synchronous collection-19 broadcast. */
  return;
}

